function polygon(g,points,color){g.fillStyle=color;g.beginPath();points.forEach(([x,y],i)=>i?g.lineTo(x,y):g.moveTo(x,y));g.closePath();g.fill();}
function block(g,x,y,w,h,color){g.fillStyle=color;g.fillRect(x,y,w,h);polygon(g,[[x,y],[x+5,y-4],[x+w+5,y-4],[x+w,y]],'#a5b3b266');polygon(g,[[x+w,y],[x+w+5,y-4],[x+w+5,y+h-4],[x+w,y+h]],'#091b2866');g.strokeStyle='#07101588';g.lineWidth=1;g.strokeRect(x+.5,y+.5,w,h);}
function cylinder(g,x,y,w,h,color){let grad=g.createLinearGradient(x,0,x+w,0);grad.addColorStop(0,'#1a3544');grad.addColorStop(.25,color);grad.addColorStop(.6,color);grad.addColorStop(1,'#233746');g.fillStyle=grad;g.fillRect(x,y,w,h);g.beginPath();g.ellipse(x+w/2,y,w/2,5,0,0,7);g.fillStyle='#9bafb3';g.fill();g.strokeStyle='#c6dadd66';g.stroke();g.beginPath();g.ellipse(x+w/2,y+h,w/2,5,0,0,7);g.fillStyle='#263c45';g.fill();}
