if(b==='generator'){cylinder(g,25,41,52,38,'#83949a');block(g,77,37,52,47,'#59727a');for(let y=52;y<79;y+=5){g.fillStyle='#122934';g.fillRect(84,y,38,2);}screen(g,84,41,22,8,lit);block(g,20,84,115,5,'#586770');g.strokeStyle='#c09a68';g.lineWidth=5;g.beginPath();g.moveTo(123,39);g.lineTo(137,39);g.lineTo(137,18);g.stroke();for(let x of [30,49,65]){g.fillStyle='#394c53';g.fillRect(x,44,3,36);}}
