if(b==='farm'){for(let y of [44,72]){block(g,23,y,109,7,'#91aaa0');g.fillStyle='#372f28';g.fillRect(27,y-3,101,3);for(let x=31;x<132;x+=13){g.strokeStyle='#80d14d';g.lineWidth=2;g.beginPath();g.moveTo(x,y);g.lineTo(x,y-15);g.stroke();g.fillStyle='#b0ee67';g.beginPath();g.ellipse(x-4,y-10,5,2.7,-.5,0,7);g.ellipse(x+4,y-14,5,2.7,.5,0,7);g.fill();}g.fillStyle=power?'#dcecb4':'#64736c';g.fillRect(25,y-22,106,2);}g.fillStyle='#7d9e90';g.fillRect(20,24,3,60);g.fillRect(135,24,3,60);}
