// Continuous world-coordinate geology: layer edges cross cell boundaries.
function strataEdge(k,wx){return k*160+Math.sin(wx*.0032+k*.91)*27+Math.sin(wx*.009+k*1.7)*8;}
function terrainHash(a,b){let h=Math.imul(a+731,374761393)^Math.imul(b+193,668265263);return ((Math.imul(h^(h>>>13),1274126177)^(h>>>16))>>>0)/4294967296;}
function rock(g,x,y,seen,feature,large=false){let ox=x*TW,oy=y*TH,palette=['#405465','#59616b','#615e56','#465868','#756a5b','#465361'];g.fillStyle='#435361';g.fillRect(0,0,TW,TH);for(let k=Math.floor((oy-50)/160);k<=Math.ceil((oy+TH+50)/160);k++){let top=[],bottom=[];for(let dx=0;dx<=TW;dx+=20){top.push([dx,strataEdge(k,ox+dx)-oy]);bottom.unshift([dx,strataEdge(k+1,ox+dx)-oy]);}polygon(g,[...top,...bottom],palette[((k%6)+6)%6]);g.strokeStyle='#141d2440';g.lineWidth=3;g.beginPath();for(let [dx,dy] of top)dx?g.lineTo(dx,dy):g.moveTo(dx,dy);g.stroke();g.strokeStyle='#a3a18b18';g.lineWidth=1;g.beginPath();for(let [dx,dy] of top)dx?g.lineTo(dx,dy+3):g.moveTo(dx,dy+3);g.stroke();}
// Broad irregular facets add depth without outlining excavation cells.
for(let rx=Math.floor((ox-220)/240);rx<=Math.floor((ox+TW)/240);rx++)for(let ry=Math.floor((oy-160)/165);ry<=Math.floor((oy+TH)/165);ry++){let px=rx*240+terrainHash(rx+4,ry)*95-ox,py=ry*165+terrainHash(ry+5,rx)*70-oy;let pts=[[px,py],[px+95,py-22],[px+177,py+29],[px+151,py+105],[px+36,py+122],[px-18,py+59]];polygon(g,pts,terrainHash(rx,ry)>.5?'#d5bb8b16':'#102b451e');g.strokeStyle='#151f2520';g.lineWidth=1;g.beginPath();g.moveTo(px,py);g.lineTo(px+95,py-22);g.lineTo(px+177,py+29);g.stroke();}
// Fine mineral grain, positioned deterministically in global space.
for(let k=0;k<100;k++){let dx=terrainHash(ox+k,oy+13)*TW,dy=terrainHash(oy+k,ox+7)*TH;g.fillStyle=k%3?'#e0caa025':'#0c26372a';g.fillRect(dx,dy,1+terrainHash(k+x,y)*2,.7);if(k%9===0){g.fillStyle='#ead4a91c';g.beginPath();g.ellipse(dx,dy,3+terrainHash(k,y)*5,1.2,k,0,7);g.fill();}}
// Fractures belong to large regions rather than every excavation cell.
for(let rx=Math.floor((ox-220)/430);rx<=Math.floor((ox+TW+220)/430);rx++)for(let ry=Math.floor((oy-150)/290);ry<=Math.floor((oy+TH+150)/290);ry++){let px=rx*430+terrainHash(rx,ry)*180,py=ry*290+terrainHash(ry,rx)*160;g.strokeStyle='#121f2766';g.lineWidth=1.4;g.beginPath();g.moveTo(px-ox,py-oy);for(let j=1;j<6;j++)g.lineTo(px-ox+Math.sin(j*1.9+rx)*38+j*14,py-oy+j*34);g.stroke();if(terrainHash(rx+23,ry)>.65){g.strokeStyle='#b6ac8628';g.lineWidth=2;g.beginPath();g.moveTo(px-ox+60,py-oy+55);g.bezierCurveTo(px-ox+85,py-oy+100,px-ox+30,py-oy+120,px-ox+70,py-oy+175);g.stroke();}}
if(seen){let light=g.createRadialGradient(TW*.5,TH*.5,2,TW*.5,TH*.5,TW*.8);light.addColorStop(0,'#dfbf8025');light.addColorStop(1,'#c3b48d00');g.fillStyle=light;g.fillRect(0,0,TW,TH);}if(seen&&feature)drawDepositBadge(g,feature,large);}
export const DEPOSITS={metal:{name:'Металл',color:'#ff922e',hint:'Раскопка даёт 24 металла'},ore:{name:'Руда',color:'#c5a0ed',hint:'Раскопай → шахта → плавильня → металл'},fuel:{name:'Топливо',color:'#ff963e',hint:'Раскопай и построй буровую'},lake:{name:'Вода',color:'#35d9ff',hint:'Раскопка добавит 1000 подземной воды; нужна водоочистка'},gas:{name:'Газ',color:'#b7ff37',hint:'Опасный карман: вентиляция уменьшает урон'},ruin:{name:'Тайник',color:'#548fff',hint:'Раскопка даёт 40 топлива и 10 инструментов'},cave:{name:'Пещера',color:'#f1e6cb',hint:'Природная пустота'}};
export function depositDescription(c){let d=DEPOSITS[c.feature];if(!d)return 'Обычная порода · раскопка: 10 породы и 3 материала';return (c.depositTier===2?'Средняя залежь · '+d.name:c.largeDeposit?({lake:'Большая вода',ore:'Большой рудник',fuel:'Большое топливо'})[c.feature]||d.name:d.name)+' · '+(c.feature==='lake'?(c.type==='open'?'Водоносный слой вскрыт; запас передан бункеру. Нужна водоочистка':'Раскопка добавит '+(c.waterReserve??1000)+' подземной воды; нужна водоочистка'):d.hint)+(c.feature==='ore'?' · остаток '+Math.floor(c.oreReserve||0)+' кг':c.feature==='fuel'?' · остаток '+Math.floor(c.fuelReserve||0)+' л':'');}
export function depositTier(c){if(c.largeDeposit)return 3;return c.depositTier===2?2:1;}
export function drawDepositBadge(g,feature,size=1){let d=DEPOSITS[feature];if(!d)return;let count=size===true?3:Math.max(1,Math.min(3,Number(size)||1));g.save();g.translate(80-(count-1)*10,56);g.lineWidth=1.2;g.strokeStyle='#101b29';g.fillStyle=d.color;for(let i=0;i<count;i++){g.save();g.translate(i*20,0);g.beginPath();if(feature==='lake'||feature==='fuel'){g.moveTo(0,-10);g.bezierCurveTo(-3,-5,-8,1,-7,5);g.bezierCurveTo(-6,13,6,13,7,5);g.bezierCurveTo(8,1,3,-5,0,-10);g.closePath();g.fill();g.stroke();g.strokeStyle='#ffffffaa';g.beginPath();g.moveTo(-4,3);g.quadraticCurveTo(-5,7,-2,8);g.stroke();}else if(feature==='ore'||feature==='metal'){polygon(g,[[-8,5],[-5,-4],[5,-4],[8,5]],d.color);polygon(g,[[-5,-4],[-2,-7],[8,-7],[5,-4]],'#e5d4ff');g.strokeRect(-7,5,14,1);}else if(feature==='gas'){g.arc(-4,2,4,0,7);g.arc(2,-3,5,0,7);g.arc(6,3,4,0,7);g.fill();g.stroke();}else if(feature==='ruin'){g.rect(-7,-5,14,12);g.fill();g.stroke();g.fillStyle='#cde1ff';g.fillRect(-1,-5,2,12);}else{g.moveTo(-8,8);g.lineTo(-8,0);g.bezierCurveTo(-8,-12,8,-12,8,0);g.lineTo(8,8);g.closePath();g.fill();g.fillStyle='#13212a';g.fillRect(-4,-1,8,9);}g.restore();}g.restore();}


function rockRim(g,s,c){for(let [dx,dy] of [[-1,0],[1,0],[0,-1],[0,1]]){let n=s.cells[(c.y+dy)*W+c.x+dx];if(c.x+dx<0||c.x+dx>=W||c.y+dy<0||c.y+dy>=H||n?.type!=='open')continue;let shade=dx?g.createLinearGradient(dx<0?0:TW,0,dx<0?23:TW-23,0):g.createLinearGradient(0,dy<0?0:TH,0,dy<0?20:TH-20);shade.addColorStop(0,'#060d15b0');shade.addColorStop(1,'#060d1500');g.fillStyle=shade;g.fillRect(dx<0?0:dx>0?TW-23:0,dy<0?0:dy>0?TH-20:0,dx?23:TW,dy?20:TH);}}
function cached(c,power){let key=c.type==='rock'?`r${c.x},${c.y},${c.seen},${c.feature},${depositTier(c)}`:`b${c.building},${power},${(c.x+c.y)%3}`;if(!cache.has(key)){let canvas=document.createElement('canvas');canvas.width=TW;canvas.height=TH;let g=canvas.getContext('2d');if(c.type==='rock')rock(g,c.x,c.y,c.seen,c.feature,depositTier(c));else{background(g,c,power);furniture(g,c,power);decor(g,c,power);architecturalDetails(g,c,power);}cache.set(key,canvas);}return cache.get(key);}
export function draw(ctx,s,cam,width,height,selected,tool,t,selectedRoom=null){constrainDistrictCamera(s,cam,width,height);ctx.fillStyle='#0b151d';ctx.fillRect(0,0,width,height);ctx.save();ctx.translate(cam.x,cam.y);ctx.scale(cam.z,cam.z);let area=s.bunkerBounds?{x:0,y:0,w:s.bunkerBounds.w,h:s.bunkerBounds.h}:cam.all?{x:0,y:0,w:W,h:H}:DISTRICTS[s.activeDistrict||0];ctx.beginPath();ctx.rect(area.x*TW,area.y*TH,area.w*TW,area.h*TH);ctx.clip();let minX=Math.max(area.x,Math.floor(-cam.x/cam.z/TW)),maxX=Math.min(area.x+area.w,Math.ceil((width-cam.x)/cam.z/TW)),minY=Math.max(area.y,Math.floor(-cam.y/cam.z/TH)),maxY=Math.min(area.y+area.h,Math.ceil((height-cam.y)/cam.z/TH));for(let y=minY;y<maxY;y++)for(let x=minX;x<maxX;x++){let c=s.cells[y*W+x],running=c.building?roomReport(s,c).utilization>0:false;ctx.save();ctx.translate(x*TW,y*TH);ctx.drawImage(cached(c,s.resources.energy>1),0,0);if(c.type==='rock')rockRim(ctx,s,c);if(c.type==='open'&&!c.building&&c.largeDeposit)drawDepositBadge(ctx,c.feature,true);if(c.type==='rock'&&c.seen&&tool==='dig'){ctx.strokeStyle='#e3b67777';ctx.lineWidth=1;ctx.strokeRect(4,4,TW-8,TH-8);}if(c.building==='vent'){ctx.save();ctx.translate(78,57);ctx.rotate(running?t*5:0);for(let k=0;k<4;k++){ctx.rotate(Math.PI/2);polygon(ctx,[[0,0],[6,2],[11,15],[0,18]],'#96afb5');}ctx.restore();}if(running&&c.building==='generator'){ctx.fillStyle='#f7cd79';for(let k=0;k<3;k++)ctx.fillRect(91+k*10,48,5,2+Math.sin(t*5+k)*1);ctx.strokeStyle='#a6c5c655';ctx.lineWidth=1;ctx.beginPath();ctx.arc(50,60,11,t*3,t*3+Math.PI*1.6);ctx.stroke();}if(c.building==='drill'){if(running){ctx.strokeStyle='#e7cd97';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(58,40+Math.sin(t*9)*4);ctx.lineTo(58,87);ctx.stroke();}}if(c.building==='radio'&&running){ctx.strokeStyle='#9de1d666';ctx.lineWidth=1;for(let k=0;k<2;k++){let r=6+(t*9+k*11)%22;ctx.beginPath();ctx.arc(113,19,r,-1.5,-.1);ctx.stroke();}}if(c.building&&c.building!=='home'&&c.building!=='storage'&&c.building!=='stairs'&&c.building!=='corridor'){ctx.fillStyle=running?'#90e7b8':'#d59860';ctx.beginPath();ctx.arc(137,28,2,0,7);ctx.fill();}roomEffects(ctx,c,t,running,s.resources.energy>1);supplyEffects(ctx,c,t);if(selectedRoom?.x===x&&selectedRoom?.y===y){ctx.strokeStyle='#ffe1a0';ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(3,11,TW-6,91,5);ctx.stroke();}ctx.restore();}
if(selectedRoom){let c=s.cells[selectedRoom.y*W+selectedRoom.x];if(c?.type==='rock'&&c.seen){ctx.save();let x=c.x*TW,y=c.y*TH;ctx.fillStyle='#081724f0';ctx.strokeStyle=DEPOSITS[c.feature]?.color||'#dbe4eb';ctx.lineWidth=1.5;ctx.beginPath();ctx.roundRect(x-30,y-40,220,34,5);ctx.fill();ctx.stroke();ctx.fillStyle=ctx.strokeStyle;ctx.font='bold 12px system-ui';ctx.textAlign='center';ctx.fillText(depositDescription(c),x+80,y-18,206);ctx.restore();}if(c&&supplyInputs[c.building])drawSupplyLink(ctx,s,c,t);}for(let j of s.jobs){if(!s.bunkerBounds&&!cam.all&&districtOf(j.x,j.y)!==(s.activeDistrict||0))continue;let x=j.x*TW,y=j.y*TH;ctx.strokeStyle=j.type==='dismantle'?'#ff9c89':'#ebbb78';ctx.setLineDash([7,5]);ctx.strokeRect(x+4,y+4,TW-8,TH-8);ctx.setLineDash([]);ctx.fillStyle='#122735';ctx.fillRect(x+20,y+TH-6,TW-40,5);ctx.fillStyle='#ebbb78';ctx.fillRect(x+20,y+TH-6,(TW-40)*Math.min(1,j.progress/j.total),5);if(j.type==='dismantle'&&cam.z>=.8){ctx.font='bold 10px system-ui';ctx.textAlign='center';ctx.fillStyle='#ffd1b6';ctx.fillText('РАЗБОРКА',x+TW/2,y+22);}if(j.type==='dig'||j.type==='dismantle')for(let k=0;k<13;k++){let f=(t*.9+k*.13)%1;ctx.fillStyle=`rgba(219,196,152,${1-f})`;ctx.beginPath();ctx.arc(x+TW*.6+Math.sin(k*17)*f*40,y+TH*.5+f*35,1.5,0,7);ctx.fill();}}
for(let p of s.people){if(!s.bunkerBounds&&!cam.all&&districtOf(p.x,p.y)!==(s.activeDistrict||0))continue;if(p.x<minX-1||p.x>maxX||p.y<minY-1||p.y>maxY)continue;let pose=residentPose(s,p),x=pose.x,y=pose.y;ctx.save();ctx.translate(x,y);if(pose.kind==='sleep')sleeping(ctx,p,t,selected===p.id);else{if(pose.kind==='sit')seated(ctx,p,t,selected===p.id);else human(ctx,p,t,selected===p.id,pose.kind==='operate');if(pose.kind==='operate')operate(ctx,p,pose.building,t);}ctx.restore();}for(let y=minY;y<maxY;y++)for(let x=minX;x<maxX;x++){let c=s.cells[y*W+x];if(!c.building)continue;ctx.save();ctx.translate(x*TW,y*TH);drawRoomAlert(ctx,s,c,t,cam.z);roomBars(ctx,s,c,cam.z,s.jobs.some(j=>j.x===x&&j.y===y));ctx.restore();}if(cam.all)drawCitizenRoutes(ctx,s,cam.z,selected);else drawPortals(ctx,s,cam.z,t);ctx.restore();let v=ctx.createRadialGradient(width*.5,height*.5,width*.3,width*.5,height*.5,width*.8);v.addColorStop(0,'#0000');v.addColorStop(1,'#07182b44');ctx.fillStyle=v;ctx.fillRect(0,0,width,height);}

const clothes=['#ffb34f','#49d5c7','#83a8ff','#d79cfc','#f78996','#9fd663','#7cd8f4','#e2c174'];
const skins=['#f0c49a','#e2a37e','#c98d69','#ffd9b7'];
