function human(g,p,t,selected,operating=false){let coat=clothes[p.id%clothes.length],skin=skins[p.id%4],hair=hairs[p.id%6],walk=p.path.length?Math.sin(t*(8+p.id%4)+p.id)*4:0,working=(p.job||p.campaignProject&&p.task==='Прокладка тоннеля')&&p.path.length===0,bob=p.path.length?Math.abs(walk)*.35:Math.sin(t*2+p.id)*.35;g.fillStyle='#03122399';g.beginPath();g.ellipse(0,2,13,3,0,0,7);g.fill();if(p.health<=0){block(g,-14,-5,28,5,'#8595a4');return;}g.translate(0,-bob);if(p.path.length){block(g,-13,-36,9,18,'#657f79');g.fillStyle='#edb967';g.fillRect(-12,-31,5,2);}g.lineCap='round';g.lineJoin='round';g.strokeStyle='#263b59';g.lineWidth=5;g.beginPath();g.moveTo(-4,-20);g.lineTo(-5-walk*.3,-10);g.lineTo(-6+walk,-1);g.moveTo(4,-20);g.lineTo(5+walk*.3,-10);g.lineTo(6-walk,-1);g.stroke();g.strokeStyle='#82a0c8';g.lineWidth=1;g.beginPath();g.moveTo(-4,-18);g.lineTo(-6+walk,-2);g.moveTo(4,-18);g.lineTo(6-walk,-2);g.stroke();g.fillStyle='#243244';g.fillRect(-9+walk,-2,7,3);g.fillRect(3-walk,-2,7,3);let body=g.createLinearGradient(-8,0,8,0);body.addColorStop(0,coat);body.addColorStop(.5,coat);body.addColorStop(1,'#42536b');polygon(g,[[-6,-37],[6,-37],[9,-21],[-9,-21]],coat);g.fillStyle=body;g.fillRect(-6,-35,12,12);g.fillStyle='#fff0b9';g.fillRect(-7,-32,14,2);g.fillStyle='#31445e';g.fillRect(-8,-22,16,3);g.fillStyle='#e8d6ae';g.fillRect(-2,-22,4,3);g.strokeStyle=coat;g.lineWidth=5;g.beginPath();g.moveTo(-6,-35);g.lineTo(-10,-26);g.lineTo(-11-walk*.5,-19);g.moveTo(6,-35);g.lineTo(11,-28);g.lineTo((working||operating)?17:11+walk*.5,(working||operating)?-29+Math.sin(t*8)*5:-19);g.stroke();g.fillStyle=skin;g.beginPath();g.arc(-11-walk*.5,-18,2.5,0,7);g.arc((working||operating)?17:11+walk*.5,(working||operating)?-29+Math.sin(t*8)*5:-18,2.5,0,7);g.fill();g.fillRect(-3,-39,6,5);if(p.id%4===1){g.fillStyle=hair;g.beginPath();g.ellipse(0,-46,9,11,0,0,7);g.fill();}g.fillStyle=skin;g.beginPath();g.ellipse(0,-45,7,8,0,0,7);g.fill();g.fillStyle=hair;g.beginPath();g.ellipse(0,-50,7.5,4,.12,Math.PI,Math.PI*2);g.fill();polygon(g,[[-7,-49],[-1,-53],[5,-50],[-6,-46]],hair);if(p.id%4===2){g.fillStyle=hair;g.beginPath();g.arc(6,-48,4,0,7);g.fill();}g.fillStyle='#2c3043';for(let x of [-2.8,2.8]){if(p.fatigue>50||(t+p.id*.57)%5<.12){g.fillRect(x-1.1,-44,2.2,.7);}else {g.beginPath();g.ellipse(x,-45,1,1.3,0,0,7);g.fill();g.fillStyle='#fff6e5';g.fillRect(x-.35,-45.8,.6,.6);g.fillStyle='#2c3043';}}g.strokeStyle=hair;g.lineWidth=.8;g.beginPath();g.moveTo(-4,-48);g.lineTo(-1.5,-48.5);g.moveTo(1.5,-48.5);g.lineTo(4,-48);g.stroke();g.fillStyle='#e59283aa';g.beginPath();g.ellipse(-4.6,-42,1.5,.8,0,0,7);g.ellipse(4.6,-42,1.5,.8,0,0,7);g.fill();g.strokeStyle='#994e51';g.lineWidth=1;g.beginPath();if(p.health<50||p.hunger>70){g.moveTo(-2,-39.5);g.quadraticCurveTo(0,-41.5,2,-39.5);}else{g.moveTo(-2,-41);g.quadraticCurveTo(0,-38.7,2,-41);}g.stroke();if(p.id%5===3){g.strokeStyle='#2f4660';g.lineWidth=.7;g.strokeRect(-5,-47,4,3);g.strokeRect(1,-47,4,3);g.beginPath();g.moveTo(-1,-45);g.lineTo(1,-45);g.stroke();}if(working||p.profession==='Строитель'){g.fillStyle='#ffd05b';g.beginPath();g.ellipse(0,-51,8,4,0,Math.PI,Math.PI*2);g.fill();g.fillRect(-9,-52,18,2);g.fillStyle='#fff2b0';g.fillRect(-1,-55,2,3);}if(working){g.strokeStyle='#dfeaf0';g.lineWidth=2;let yy=-36+Math.sin(t*8)*5;g.beginPath();g.moveTo(17,yy+12);g.lineTo(17,yy-4);g.moveTo(11,yy-4);g.lineTo(23,yy-4);g.stroke();}if(p.health<50){g.fillStyle='#ff8e8e';g.fillRect(-7,-63,14,3);}if(selected){g.strokeStyle='#ffe797';g.lineWidth=1.5;g.beginPath();g.ellipse(0,-28,22,33,0,0,7);g.stroke();g.font='bold 11px system-ui';g.textAlign='center';g.fillStyle='#fff3bf';g.fillText(p.name,0,-70);}}
export function portrait(p){let coat=clothes[p.id%8],skin=skins[p.id%4],hair=hairs[p.id%6],sad=p.health<50||p.hunger>70,tired=p.fatigue>50,helmet=p.profession==='Строитель',glasses=p.id%5===3;return `<svg viewBox="0 0 120 120" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Портрет жителя"><defs><linearGradient id="bg${p.id}" x2="1" y2="1"><stop stop-color="#638ab8"/><stop offset="1" stop-color="#23395a"/></linearGradient></defs><rect width="120" height="120" rx="16" fill="url(#bg${p.id})"/><circle cx="62" cy="50" r="43" fill="${coat}" opacity=".14"/><path d="M13 120 Q17 85 43 82 L77 82 Q105 89 108 120" fill="${coat}"/><path d="M45 80 L46 92 Q60 104 74 92 L75 78" fill="${skin}"/><path d="M41 83 L58 102 L45 114 L34 86 M79 83 L62 102 L75 114 L86 86" fill="#fff1c5" opacity=".6"/><rect x="21" y="109" width="77" height="5" fill="#fff0b7"/><ellipse cx="60" cy="47" rx="32" ry="37" fill="${hair}"/><ellipse cx="31" cy="58" rx="5" ry="8" fill="${skin}"/><ellipse cx="89" cy="58" rx="5" ry="8" fill="${skin}"/><path d="M31 36 Q61 15 89 38 L88 62 Q86 88 61 90 Q36 89 32 63 Z" fill="${skin}"/><path d="M28 48 Q23 17 51 12 Q87 6 93 39 L82 49 L80 32 Q60 41 37 30 L36 48 Z" fill="${hair}"/>${p.id%4===2?`<circle cx="90" cy="31" r="13" fill="${hair}"/>`:''}<path d="M40 48 Q46 ${sad?44:45} 52 48 M69 48 Q76 ${sad?44:45} 83 48" fill="none" stroke="${hair}" stroke-width="3" stroke-linecap="round"/>${tired?'<path d="M42 56 L51 56 M70 56 L80 56" stroke="#30334a" stroke-width="3"/>':'<ellipse cx="47" cy="56" rx="4" ry="5" fill="#30334a"/><ellipse cx="75" cy="56" rx="4" ry="5" fill="#30334a"/><circle cx="48" cy="54" r="1.5" fill="white"/><circle cx="76" cy="54" r="1.5" fill="white"/>'}<path d="M60 58 L58 65 L63 65" fill="none" stroke="#b97f68" stroke-width="2" stroke-linecap="round"/><ellipse cx="41" cy="66" rx="6" ry="3" fill="#e99487" opacity=".65"/><ellipse cx="81" cy="66" rx="6" ry="3" fill="#e99487" opacity=".65"/><path d="${sad?'M49 77 Q61 68 72 77':'M49 73 Q60 84 72 73'}" fill="none" stroke="#8c4550" stroke-width="2.5" stroke-linecap="round"/>${glasses?'<g fill="none" stroke="#36495d" stroke-width="2"><rect x="36" y="50" width="21" height="14" rx="4"/><rect x="65" y="50" width="21" height="14" rx="4"/><path d="M57 55 L65 55"/></g>':''}${helmet?'<path d="M27 35 Q29 7 59 6 Q88 7 94 35 Z" fill="#ffd267"/><path d="M22 34 L97 34 L97 41 L22 41 Z" fill="#f3b547"/><path d="M57 9 L63 9 L63 34 L57 34 Z" fill="#fff1a0"/>':''}<circle cx="108" cy="12" r="5" fill="${p.health<50?'#ff9c9c':'#a6f3ba'}"/></svg>`;}

