 for(let x of [30,107]){block(g,x,25,15,13,'#e9c791');g.fillStyle='#9fbacd';g.fillRect(x+2,27,11,9);g.fillStyle='#fae0b1';g.beginPath();g.arc(x+7,31,2,0,7);g.fill();g.fillStyle='#789d75';g.fillRect(x+3,33,9,3);}
